enhanced_schema:
{
  "tables": [
    {
      "table_name": "powerlifting_event_results",
      "table_description": "Records of results from powerlifting competitions, capturing individual performances and rankings.",
      "columns": [
        {
          "name": "result_id",
          "type": "INTEGER",
          "description": "Unique identifier for each competition result entry"
        },
        {
          "name": "athlete_id",
          "type": "INTEGER",
          "description": "Unique identifier for the athlete"
        },
        {
          "name": "competition_id",
          "type": "INTEGER",
          "description": "Unique identifier for the competition"
        },
        {
          "name": "event_id",
          "type": "INTEGER",
          "description": "Unique identifier for the event type"
        },
        {
          "name": "place",
          "type": "INTEGER",
          "description": "Place or rank achieved in the competition"
        },
        {
          "name": "team_id",
          "type": "INTEGER",
          "description": "Identifier for the team the athlete represents"
        },
        {
          "name": "bodyweight_kg",
          "type": "FLOAT",
          "description": "Bodyweight of the athlete in kilograms"
        },
        {
          "name": "best_squat_kg",
          "type": "FLOAT",
          "description": "Best squat lift in kilograms"
        },
        {
          "name": "best_bench_kg",
          "type": "FLOAT",
          "description": "Best bench press lift in kilograms"
        },
        {
          "name": "best_deadlift_kg",
          "type": "FLOAT",
          "description": "Best deadlift in kilograms"
        },
        {
          "name": "total_kg",
          "type": "FLOAT",
          "description": "Total weight lifted across all events in kilograms"
        },
        {
          "name": "performance_rating",
          "type": "FLOAT",
          "description": "Normalized performance metric like Wilks score"
        },
        {
          "name": "eligibility_status",
          "type": "BOOLEAN",
          "description": "Eligibility status of the athlete for the event"
        },
        {
          "name": "competition_date",
          "type": "DATE",
          "description": "Date of the competition"
        }
      ],
      "primary_key": [
        "result_id"
      ],
      "foreign_keys": [
        {
          "column": "athlete_id",
          "references": "athletes(athlete_id)"
        },
        {
          "column": "competition_id",
          "references": "competitions(competition_id)"
        },
        {
          "column": "event_id",
          "references": "events(event_id)"
        },
        {
          "column": "team_id",
          "references": "teams(team_id)"
        }
      ]
    },
    {
      "table_name": "athletes",
      "table_description": "Detailed information about each athlete.",
      "columns": [
        {
          "name": "athlete_id",
          "type": "INTEGER",
          "description": "Unique identifier for the athlete"
        },
        {
          "name": "full_name",
          "type": "VARCHAR",
          "description": "Full name of the athlete"
        },
        {
          "name": "birth_date",
          "type": "DATE",
          "description": "Birth date of the athlete"
        },
        {
          "name": "sex",
          "type": "CHAR",
          "description": "Sex of the athlete (M or F)"
        },
        {
          "name": "nationality",
          "type": "VARCHAR",
          "description": "Nationality of the athlete"
        },
        {
          "name": "registration_status",
          "type": "BOOLEAN",
          "description": "Registration status of the athlete"
        }
      ],
      "primary_key": [
        "athlete_id"
      ]
    },
    {
      "table_name": "teams",
      "table_description": "Information about teams and their affiliations.",
      "columns": [
        {
          "name": "team_id",
          "type": "INTEGER",
          "description": "Unique identifier for the team"
        },
        {
          "name": "team_name",
          "type": "VARCHAR",
          "description": "Name of the team"
        },
        {
          "name": "coach_name",
          "type": "VARCHAR",
          "description": "Name of the team's coach"
        },
        {
          "name": "affiliation",
          "type": "VARCHAR",
          "description": "Affiliation of the team"
        },
        {
          "name": "region",
          "type": "VARCHAR",
          "description": "Region or locality of the team"
        }
      ],
      "primary_key": [
        "team_id"
      ]
    },
    {
      "table_name": "competitions",
      "table_description": "Details about each competition event.",
      "columns": [
        {
          "name": "competition_id",
          "type": "INTEGER",
          "description": "Unique identifier for the competition"
        },
        {
          "name": "competition_name",
          "type": "VARCHAR",
          "description": "Name of the competition"
        },
        {
          "name": "location",
          "type": "VARCHAR",
          "description": "Location where the competition is held"
        },
        {
          "name": "start_date",
          "type": "DATE",
          "description": "Start date of the competition"
        },
        {
          "name": "end_date",
          "type": "DATE",
          "description": "End date of the competition"
        },
        {
          "name": "division",
          "type": "VARCHAR",
          "description": "Division category of the competition"
        }
      ],
      "primary_key": [
        "competition_id"
      ]
    },
    {
      "table_name": "events",
      "table_description": "Management of event types and equipment used.",
      "columns": [
        {
          "name": "event_id",
          "type": "INTEGER",
          "description": "Unique identifier for the event type"
        },
        {
          "name": "event_name",
          "type": "VARCHAR",
          "description": "Name of the event type"
        },
        {
          "name": "equipment_type",
          "type": "VARCHAR",
          "description": "Type of equipment used in the event"
        }
      ],
      "primary_key": [
        "event_id"
      ]
    },
    {
      "table_name": "user_management",
      "table_description": "User roles and access level management.",
      "columns": [
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "Unique identifier for the user"
        },
        {
          "name": "username",
          "type": "VARCHAR",
          "description": "Username for login"
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "Role of the user (e.g., athlete, coach, organizer)"
        },
        {
          "name": "email",
          "type": "VARCHAR",
          "description": "Email address of the user"
        },
        {
          "name": "password_hash",
          "type": "VARCHAR",
          "description": "Hashed password for secure authentication"
        },
        {
          "name": "last_login",
          "type": "DATETIME",
          "description": "Timestamp of the user's last login"
        }
      ],
      "primary_key": [
        "user_id"
      ]
    }
  ]
}
